private extension DeviceDefinition {
    static func detected(
        _ productID: UInt16,
        _ name: String,
        _ kind: DeviceKind
    ) -> Self {
        return .init(
            productID: productID,
            name: name,
            kind: kind,
            transactionID: 0,
            lightingProtocol: nil,
            supportLevel: .detectionOnly,
            targets: [],
            supportedEffects: [],
            supportsBrightness: false
        )
    }

    static func supported(
        _ productID: UInt16,
        _ name: String,
        _ kind: DeviceKind,
        transactionID: UInt8,
        protocol lightingProtocol: LightingProtocol,
        targets: [LightingTarget],
        supportedEffects explicitSupportedEffects: Set<LightingEffectKind>? = nil
    ) -> Self {
        var supportedEffects = explicitSupportedEffects ?? Set(LightingEffectKind.allCases)
        if lightingProtocol == .mouseExtendedMatrix {
            supportedEffects.remove(.wave)
            supportedEffects.remove(.starlight)
        }
        if kind == .mouse {
            supportedEffects.remove(.starlight)
        }
        if kind != .keyboard && kind != .laptop {
            supportedEffects.remove(.ripple)
            supportedEffects.remove(.wheel)
        }

        return .init(
            productID: productID,
            name: name,
            kind: kind,
            transactionID: transactionID,
            lightingProtocol: lightingProtocol,
            supportLevel: .community,
            targets: targets,
            supportedEffects: supportedEffects,
            supportsBrightness: true
        )
    }
}
